import{_ as e,c as o,o as d,ae as l}from"./chunks/framework.CDjunVez.js";const h=JSON.parse('{"title":"ジェネレーターの準備","description":"","frontmatter":{},"headers":[],"relativePath":"ja/manual/generator_preparation.md","filePath":"ja/manual/generator_preparation.md"}'),a={name:"ja/manual/generator_preparation.md"};function n(c,t,s,i,r,g){return d(),o("div",null,[...t[0]||(t[0]=[l('<h1 id="ジェネレーターの準備" tabindex="-1">ジェネレーターの準備 <a class="header-anchor" href="#ジェネレーターの準備" aria-label="Permalink to &quot;ジェネレーターの準備&quot;">​</a></h1><p>Extended Note Block（拡張音符ブロック）は多くのカスタムNBTタグを持っており、これらを利用することで、従来の音符ブロックよりも豊かな音楽効果を実現できます。これは、コマンドブロックや外部ジェネレーターを使用して音符ブロックを一括生成する場合に非常に役立ちます。</p><h2 id="nbt構造の概要" tabindex="-1">NBT構造の概要 <a class="header-anchor" href="#nbt構造の概要" aria-label="Permalink to &quot;NBT構造の概要&quot;">​</a></h2><p>Extended Note BlockのNBTデータは、主に<strong>基本属性</strong>と<strong>高度なデータ (AdvancedData)</strong> の2つの部分に分かれています。</p><h3 id="基本属性-root" tabindex="-1">基本属性 (Root) <a class="header-anchor" href="#基本属性-root" aria-label="Permalink to &quot;基本属性 (Root)&quot;">​</a></h3><p>これらの属性は、NBTのルートノード直下にあります。</p><table tabindex="0"><thead><tr><th style="text-align:left;">タグ名</th><th style="text-align:left;">型</th><th style="text-align:left;">説明</th><th style="text-align:left;">範囲/単位</th><th style="text-align:left;">デフォルト値</th></tr></thead><tbody><tr><td style="text-align:left;"><code>note</code></td><td style="text-align:left;">Int</td><td style="text-align:left;">MIDIピッチ</td><td style="text-align:left;">0-127 (60が中央C)</td><td style="text-align:left;">60</td></tr><tr><td style="text-align:left;"><code>velocity</code></td><td style="text-align:left;">Int</td><td style="text-align:left;">MIDIベロシティ (基本音量)</td><td style="text-align:left;">0-127</td><td style="text-align:left;">100</td></tr><tr><td style="text-align:left;"><code>sustainTime</code></td><td style="text-align:left;">Int</td><td style="text-align:left;">音符の持続時間</td><td style="text-align:left;">ゲームティック (Ticks, 20 ticks = 1秒)</td><td style="text-align:left;">40</td></tr><tr><td style="text-align:left;"><code>delayedPlayingTime</code></td><td style="text-align:left;">Int</td><td style="text-align:left;">再生遅延時間</td><td style="text-align:left;">ミリ秒 (ms)</td><td style="text-align:left;">0</td></tr><tr><td style="text-align:left;"><code>fadeInTime</code></td><td style="text-align:left;">Int</td><td style="text-align:left;">フェードイン時間</td><td style="text-align:left;">ゲームティック (Ticks)</td><td style="text-align:left;">0</td></tr><tr><td style="text-align:left;"><code>fadeOutTime</code></td><td style="text-align:left;">Int</td><td style="text-align:left;">フェードアウト時間</td><td style="text-align:left;">ゲームティック (Ticks)</td><td style="text-align:left;">0</td></tr></tbody></table><h3 id="ブロック状態-block-states" tabindex="-1">ブロック状態 (Block States) <a class="header-anchor" href="#ブロック状態-block-states" aria-label="Permalink to &quot;ブロック状態 (Block States)&quot;">​</a></h3><p>NBTデータに加えて、Extended Note BlockはBlockStatesを使用してレッドストーン信号と視覚表現を処理します。</p><table tabindex="0"><thead><tr><th style="text-align:left;">状態名</th><th style="text-align:left;">型</th><th style="text-align:left;">可能な値</th><th style="text-align:left;">説明</th></tr></thead><tbody><tr><td style="text-align:left;"><code>pitch</code></td><td style="text-align:left;">Enum</td><td style="text-align:left;"><code>c</code>, <code>cs</code>, <code>d</code>, <code>ds</code>, <code>e</code>, <code>f</code>, <code>fs</code>, <code>g</code>, <code>gs</code>, <code>a</code>, <code>as</code>, <code>b</code></td><td style="text-align:left;">1オクターブ内での現在の音符のピッチ（Note % 12）に対応します。主にリソースパックでブロックのテクスチャを変更するために使用されます。例えば、<code>cs</code> は C# を表します。</td></tr><tr><td style="text-align:left;"><code>powered</code></td><td style="text-align:left;">Boolean</td><td style="text-align:left;"><code>true</code>, <code>false</code></td><td style="text-align:left;">ブロックがレッドストーン信号によってアクティブ化されているかどうかを示します。信号エッジ（立ち上がり/立ち下がり）の検出に使用されます。</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">注意</p><p><code>setblock</code> を使用してブロックを配置する場合、通常 <code>pitch</code> を手動で指定する必要はありません。ブロックがレッドストーンによってアクティブ化されると、NBT内の <code>note</code> 値に基づいて自動的にこの状態が計算および更新されるためです。</p></div><h3 id="高度なデータ-advanceddata-compound" tabindex="-1">高度なデータ (<code>AdvancedData</code> Compound) <a class="header-anchor" href="#高度なデータ-advanceddata-compound" aria-label="Permalink to &quot;高度なデータ (`AdvancedData` Compound)&quot;">​</a></h3><p>すべての高度な機能のデータは、<code>AdvancedData</code> という名前の複合タグ内に保存されます。ジェネレーターは正確な List データ構造を構築する必要があります。</p><h4 id="_1-ピッチベンド曲線-pitchbendpoints" tabindex="-1">1. ピッチベンド曲線 (<code>PitchBendPoints</code>) <a class="header-anchor" href="#_1-ピッチベンド曲線-pitchbendpoints" aria-label="Permalink to &quot;1. ピッチベンド曲線 (`PitchBendPoints`)&quot;">​</a></h4><ul><li><strong>型</strong>: <code>List&lt;Compound&gt;</code></li><li><strong>要素構造</strong>: <code>{t: &lt;float&gt;, v: &lt;float&gt;}</code><ul><li><code>t</code> (Time): 時間点。範囲は <code>0.0</code> (開始) から <code>1.0</code> (終了) です。</li><li><code>v</code> (Value): <strong>半音 (Semitones)</strong> のオフセット量。 <ul><li><code>0.0</code>: オフセットなし（元のピッチ）。</li><li><code>12.0</code>: 1オクターブ上。</li><li><code>-12.0</code>: 1オクターブ下。</li><li>小数をサポートします。例: <code>0.5</code> 半音（50セント）。</li></ul></li></ul></li><li><strong>補間動作</strong>: ゲームは2つのキーポイント間で<strong>線形補間</strong>を行います。</li></ul><h4 id="_2-音量エンベロープ-volumepoints" tabindex="-1">2. 音量エンベロープ (<code>VolumePoints</code>) <a class="header-anchor" href="#_2-音量エンベロープ-volumepoints" aria-label="Permalink to &quot;2. 音量エンベロープ (`VolumePoints`)&quot;">​</a></h4><ul><li><strong>型</strong>: <code>List&lt;Compound&gt;</code></li><li><strong>要素構造</strong>: <code>{t: &lt;float&gt;, v: &lt;float&gt;}</code><ul><li><code>t</code> (Time): 時間点。範囲は <code>0.0</code> から <code>1.0</code> です。</li><li><code>v</code> (Value): <strong>音量倍率 (Multiplier)</strong>。 <ul><li><code>1.0</code>: 標準音量（<code>velocity</code> によって決定）。</li><li><code>0.0</code>: ミュート。</li><li><code>2.0</code>: 標準音量の2倍。</li></ul></li></ul></li><li><strong>補間動作</strong>: ゲームは2つのキーポイント間で<strong>線形補間</strong>を行います。</li><li><strong>上書きルール</strong>: このリストが空でない場合、NBTルートノードの <code>fadeInTime</code>/<code>fadeOutTime</code> は無効になります。</li></ul><h4 id="_3-音源移動パス-soundpath" tabindex="-1">3. 音源移動パス (<code>SoundPath</code>) <a class="header-anchor" href="#_3-音源移動パス-soundpath" aria-label="Permalink to &quot;3. 音源移動パス (`SoundPath`)&quot;">​</a></h4><ul><li><strong>型</strong>: <code>List&lt;Compound&gt;</code></li><li><strong>要素構造</strong>: <code>{x: &lt;double&gt;, y: &lt;double&gt;, z: &lt;double&gt;}</code><ul><li>これらの座標は<strong>音符ブロックの中心に対する相対オフセット</strong>です。例えば <code>{x:0, y:1, z:0}</code> は音符ブロックの1ブロック上を表します。</li></ul></li><li><strong>サンプリング動作</strong>: 曲線とは異なり、<code>SoundPath</code> は<strong>線形補間を行いません</strong>。 <ul><li>ゲームは現在の再生進行度に基づいてインデックス <code>Index = Progress * (Size - 1)</code> を計算し、対応する点の位置を直接取得します。</li><li><strong>推奨</strong>: スムーズな移動が必要な場合、ジェネレーターは十分に密な点を生成する必要があります（例：<code>sustainTime</code> が40 ticksの場合、1 tickにつき1点、計40個のパス点を生成することを推奨します）。</li></ul></li></ul><h4 id="_4-gui-数式キャッシュ-expressionx-y-z" tabindex="-1">4. GUI 数式キャッシュ (<code>ExpressionX</code>/<code>Y</code>/<code>Z</code>) <a class="header-anchor" href="#_4-gui-数式キャッシュ-expressionx-y-z" aria-label="Permalink to &quot;4. GUI 数式キャッシュ (`ExpressionX`/`Y`/`Z`)&quot;">​</a></h4><ul><li><strong>型</strong>: <code>String</code></li><li>これらは単なる文字列で、GUI内でユーザーが入力した数式（<code>sin(t * pi)</code> など）を表示するために使用されます。</li></ul><div class="warning custom-block"><p class="custom-block-title">重要</p><p>ゲームのコアロジックは、これらの文字列を<strong>完全に無視</strong>します。外部ジェネレーターの場合、プレイヤーがGUIを開いたときに特定の数式を表示させたい場合を除き、これらの文字列を生成する<strong>必要はありません</strong>。生成する必要があるのは、上記の <code>SoundPath</code> リストです。</p></div><h2 id="setblock-コマンドの例" tabindex="-1">Setblock コマンドの例 <a class="header-anchor" href="#setblock-コマンドの例" aria-label="Permalink to &quot;Setblock コマンドの例&quot;">​</a></h2><p><code>/setblock</code> コマンドを使用して、プリセットNBTデータを持つExtended Note Blockを配置できます。</p><p><strong>基本例：</strong></p><div class="language-mcfunction vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mcfunction</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>setblock ~ ~1 ~ extendednoteblock:extended_note_block{note:64, velocity:120, sustainTime:10}</span></span></code></pre></div><p><strong>高度な例（ピッチベンドを含む）：</strong></p><div class="language-mcfunction vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mcfunction</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>setblock ~ ~1 ~ extendednoteblock:extended_note_block{note:60, sustainTime:40, AdvancedData:{PitchBendPoints:[{t:0.0f, v:0.0f}, {t:1.0f, v:12.0f}]}}</span></span></code></pre></div><h2 id="注意事項" tabindex="-1">注意事項 <a class="header-anchor" href="#注意事項" aria-label="Permalink to &quot;注意事項&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">SoundPath と Expression の関係</p><p><code>AdvancedData</code> 内に、<code>SoundPath</code> と <code>ExpressionX/Y/Z</code> が同時に存在している場合があります。</p><ul><li><strong>Expr (数式)</strong>：<strong>GUI インターフェースの表示と編集</strong>にのみ使用されます。ゲームは実行時にこれらの数式を計算<strong>しません</strong>。</li><li><strong>SoundPath (パス)</strong>：これはゲームが実際に音声を再生する際に使用するパスデータです。</li></ul><p><strong>重要ポイント：</strong> ジェネレーターを作成する場合、<strong>必ず <code>SoundPath</code> リストデータを直接生成してください</strong>。単に <code>Expression</code> 文字列を書き込むだけでは無効であり、プレイヤーが手動でGUIを開いて保存しない限り、音源は移動しません（保存時にクライアントが数式に基づいてパス点を計算し、<code>SoundPath</code> に書き込みます）。</p></div><div class="info custom-block"><p class="custom-block-title">音量制御の優先順位</p><p>音量は主に以下の2つの属性によって制御されます：</p><ol><li><strong><code>velocity</code> (基本ベロシティ)</strong>：曲全体の基本音量を決定します。</li><li><strong><code>VolumePoints</code> (高度な音量曲線)</strong>：<code>AdvancedData</code> 内に空でない <code>VolumePoints</code> リストが存在する場合、それは基本 <code>velocity</code> の効果を<strong>完全に上書き (Override)</strong> します。</li></ol><p>つまり、動的な音量エンベロープ（ADSRなど）を使用したい場合は <code>VolumePoints</code> を使用し、単純な固定音量の場合は <code>velocity</code> を使用すればよいということです。</p></div>',31)])])}const p=e(a,[["render",n]]);export{h as __pageData,p as default};
